#!/usr/bin/env node

// src/core/format.ts
var systemLocale = typeof Intl !== "undefined" ? Intl.DateTimeFormat().resolvedOptions().locale : "en";
function fmtNumber(n, maxDecimals = 2) {
  return new Intl.NumberFormat(systemLocale, {
    maximumFractionDigits: maxDecimals
  }).format(n);
}
function splitDuration(totalSeconds) {
  const total = Math.max(0, Math.floor(totalSeconds));
  return {
    h: Math.floor(total / 3600),
    m: Math.floor(total % 3600 / 60),
    s: total % 60
  };
}

export {
  fmtNumber,
  splitDuration
};
